def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    rows = {r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background}
    cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background}
    out = [row[:] for row in grid]
    for r in rows:
        for c in range(w):
            out[r][c] = 2
    for c in cols:
        for r in range(h):
            out[r][c] = 2
    return out
